ColorFilter? decColorFilter(Object? v) {
  if (v == null) return null;
  final m = v as Map;
  switch (m[r'$']) {
    case 'mode':
      return ColorFilter.mode(fuseReq(decColor(m['color']), 'ColorFilter.mode', 'color'), fuseReq(fuseEnum(BlendMode.values, m['blendMode']), 'ColorFilter.mode', 'blendMode'));
    case 'matrix':
      return ColorFilter.matrix(fuseReq(fuseList<double>(m['matrix'], (e) => decDouble(e)!), 'ColorFilter.matrix', 'matrix'));
    case 'linearToSrgbGamma':
      return ColorFilter.linearToSrgbGamma();
    case 'srgbToLinearGamma':
      return ColorFilter.srgbToLinearGamma();
    case 'saturation':
      return ColorFilter.saturation(fuseReq(decDouble(m['saturation']), 'ColorFilter.saturation', 'saturation'));
  }
  return fuseBad('ColorFilter', v);
}

lottie.DropShadow? decDropShadow(Object? v) {
  if (v == null) return null;
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return lottie.DropShadow(color: fuseReq(decColor(m['color']), 'DropShadow', 'color'), direction: fuseReq(decDouble(m['direction']), 'DropShadow', 'direction'), distance: fuseReq(decDouble(m['distance']), 'DropShadow', 'distance'), radius: fuseReq(decDouble(m['radius']), 'DropShadow', 'radius'));
  }
  return fuseBad('lottie.DropShadow', v);
}

Offset? decOffset(Object? v) {
  if (v == null) return null;
  if (v is String) {
    return switch (v) {
      'zero' => Offset.zero,
      'infinite' => Offset.infinite,
      _ => fuseBad('Offset', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Offset(fuseReq(decDouble(m['dx']), 'Offset', 'dx'), fuseReq(decDouble(m['dy']), 'Offset', 'dy'));
    case 'fromDirection':
      return Offset.fromDirection(fuseReq(decDouble(m['direction']), 'Offset.fromDirection', 'direction'), decDouble(m['distance']) ?? 1.0);
  }
  return fuseBad('Offset', v);
}

Path? decPath(Object? v) {
  if (v == null) return null;
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Path();
    case 'from':
      return Path.from(fuseReq(decPath(m['source']), 'Path.from', 'source'));
  }
  return fuseBad('Path', v);
}

